#!/usr/bin/env python3
"""Generate goldenvess3g-vendor.mk from proprietary-files.txt and the files actually extracted.

Usage: python3 generate-vendor-mk.py [--check]
--check only reports what would be written. Needs ./proprietary/ produced by extract-files.sh.
Copies files with PRODUCT_COPY_FILES (skeleton choice; real prebuilt modules can replace this later).
"""
import os, sys
here = os.path.dirname(os.path.abspath(__file__))
check = '--check' in sys.argv
paths = []
for line in open(os.path.join(here, 'proprietary-files.txt')):
    line = line.split('#', 1)[0].strip()
    if line:
        paths.append(line)
present = [p for p in paths if os.path.isfile(os.path.join(here, 'proprietary', p[len('system/'):]))]
absent = [p for p in paths if p not in present]
print('manifest entries: %d, extracted: %d, not extracted: %d' % (len(paths), len(present), len(absent)))
if absent:
    print('NOT EXTRACTED (first 10):', absent[:10])
if check:
    sys.exit(0)
if not present:
    sys.exit('nothing extracted: run extract-files.sh against verified official firmware first')
lines = ['# GENERATED by generate-vendor-mk.py - do not edit, do not commit (git-ignored).',
         'PRODUCT_COPY_FILES += \\']
for p in present:
    lines.append('    vendor/samsung/goldenvess3g/proprietary/%s:%s \\' % (p[len('system/'):], p))
lines[-1] = lines[-1].rstrip(' \\')
open(os.path.join(here, 'goldenvess3g-vendor.mk'), 'w').write('\n'.join(lines) + '\n')
open(os.path.join(here, 'BoardConfigVendor.mk'), 'w').write('# GENERATED. Intentionally empty: no board flags come from the vendor files.\n')
print('wrote goldenvess3g-vendor.mk')
